نظرة سريعة على كود ينتهك SOLID وكود يعتمد عليها في Android:
```kotlin
// ❌ انتهاك صارخ لمبادئ SOLID: God Activity تجمع كل شيء:
class MonolithicProfileActivity : AppCompatActivity() {
    // تنتهك SRP: تجمع الرسم، واستدعاء Retrofit، وحفظ SQLite، والـ Validation!
    // تنتهك OCP: إضافة نوع مستخدم جديد يتطلب تعديل if/else في 5 دوال.
    // تنتهك DIP: تعتمد على كائنات ملموسة مباشرة new Retrofit().
}

// ✅ تطبيق SOLID: تفكيك المسؤوليات إلى مكونات متماسكة ومعزولة:
class ProfileViewModel @Inject constructor(
    private val getProfile: GetProfileUseCase, // DIP & SRP
    private val analytics: AnalyticsTracker // ISP & OCP
) : ViewModel() {
    val uiState: StateFlow<ProfileUiState> = ...
}
```

تطبيق مبدأ SRP بفصل المسؤوليات المعزولة في شاشة التسجيل:
```kotlin
// ❌ انتهاك صارخ لـ SRP: كلاس واحد يقوم بالتحقق، والشبكة، والتخزين، وتحديث الواجهة:
class BadRegistrationActivity : AppCompatActivity() {
    fun onRegisterClicked(email: String, pass: String) {
        if (!email.contains("@")) return // منطق بيزنس!
        api.register(email, pass) { response -> // اتصال شبكة!
            prefs.edit().putString("token", response.token).apply() // تخزين محلي!
            showSuccessDialog() // رسم واجهة!
        }
    }
}

// ✅ تطبيق SRP السليم: كل كائن له مسؤولية وحيدة وسبب واحد للتعديل:
class EmailValidator { // سبب التغيير: تعديل قواعد الإيميل من الـ Business
    fun isValid(email: String): Boolean = email.isNotBlank() && Patterns.EMAIL_ADDRESS.matcher(email).matches()
}

class RegisterUserUseCase(private val authRepo: AuthRepository, private val validator: EmailValidator) {
    suspend operator fun invoke(email: String, pass: String): Result<UserSession> {
        if (!validator.isValid(email)) return Result.failure(InvalidEmailException())
        return authRepo.register(email, pass)
    }
}

// الـ ViewModel مسؤول حصرياً عن إدارة الـ UI State وإطلاق الـ UseCase:
@HiltViewModel
class RegisterViewModel @Inject constructor(private val registerUser: RegisterUserUseCase) : ViewModel() { ... }
```

تطبيق نمط Strategy لتحقيق OCP في نظام معالجة المدفوعات:
```kotlin
// ❌ انتهاك صارخ لـ OCP: إضافة طريقة دفع جديدة تجبرنا على تعديل الكود القديم المعتمد:
class BadPaymentService {
    fun process(type: String, amount: Long) {
        if (type == "CREDIT_CARD") { /* كود قديم */ }
        else if (type == "PAYPAL") { /* كود قديم */ }
        else if (type == "APPLE_PAY") { /* كود جديد تم حشره هنا! */ }
        // 💥 أي خطأ هنا سيكسر الدفع بالبطاقات القديمة!
    }
}

// ✅ تطبيق OCP: مفتوح لإضافة طرق دفع جديدة دون تعديل الكود القائم إطلاقاً:
interface PaymentProcessor {
    val paymentMethod: PaymentMethod
    suspend fun pay(amountCents: Long): PaymentResult
}

class CreditCardProcessor : PaymentProcessor { ... }
class PayPalProcessor : PaymentProcessor { ... }
// إضافة طريقة دفع جديدة لا تتطلب سوى كلاس جديد مستقل:
class GooglePayProcessor : PaymentProcessor { ... }

// الكلاس المنسق مغلق للتعديل ويعتمد على خريطة الموزعين:
class PaymentRouter @Inject constructor(
    private val processors: Set<PaymentProcessor>
) {
    suspend fun executePayment(method: PaymentMethod, amount: Long): PaymentResult {
        val handler = processors.firstOrNull { it.paymentMethod == method } ?: error("Unsupported method")
        return handler.pay(amount)
    }
}
```

المقارنة بين انتهاك LSP في كلاسات الـ Base وكود متوافق مع LSP عبر الـ Delegates:
```kotlin
// ❌ انتهاك صارخ لـ LSP: إجبار الكلاس الفرعي على سلوك لا يدعمه مما يكسر التوقعات:
open class BaseFragment : Fragment() {
    open fun setupToolbar() {
        // يتوقع الكود أن كل Fragment يمتلك Toolbar صالحاً للربط
    }
}

class FullScreenVideoFragment : BaseFragment() {
    override fun setupToolbar() {
        // 💥 يكسر LSP: يرمي استثناء أو يتجاهل العقد لأن شاشة الفيديو بدون Toolbar!
        throw UnsupportedOperationException("Video screen does not have a toolbar")
    }
}

// ✅ تطبيق LSP السليم: فصل السلوك الاختياري في واجهة أو Delegate مستقل:
interface ToolbarConfigurable {
    fun configureToolbar(toolbar: Toolbar)
}

class HomeFragment : Fragment(), ToolbarConfigurable {
    override fun configureToolbar(toolbar: Toolbar) { /* إعداد Toolbar للشاشات التي تحتاجه فقط */ }
}

class VideoFragment : Fragment() {
    // لا ينفذ ToolbarConfigurable؛ لا استثناءات غير متوقعة ولا كسر للعقود!
}
```

المقارنة بين واجهة ضخمة تنتهك ISP وواجهات مجزأة دقيقة:
```kotlin
// ❌ انتهاك صارخ لـ ISP: واجهة ضخمة تجبر الكلاسات على تنفيذ دوال لا تحتاجها:
interface UserManagementService {
    fun readProfile(): User
    fun updateProfile(user: User)
    fun deleteAccount()
    fun processSubscriptionPayment(amount: Long)
}

// شاشة العرض البسيطة تضطر للتعامل مع دوال الحذف والدفع الحساسة بلا داعٍ!
class ReadOnlyProfileWidget(private val service: UserManagementService) { ... }

// ✅ تطبيق ISP السليم: واجهات دقيقة مقسمة حسب الصلاحيات والاحتياج:
fun interface UserProfileReader {
    fun readProfile(): Flow<User>
}

interface UserProfileWriter {
    suspend fun updateProfile(user: User)
}

interface AccountTerminator {
    suspend fun deleteAccount()
}

// يمكن لكلاس الـ Repository في طبقة Data تنفيذ الواجهات الثلاث معاً، ولكن الـ Widget يستهلك Reader فقط:
class ReadOnlyProfileWidget(private val reader: UserProfileReader) {
    // آمن تماماً، ولا يعرف أي شيء عن الحذف أو الدفع!
}
