// كلاس واحد محقق لمبدأ SRP (مسؤوليته الوحيدة تنسيق بيانات المستخدم في Data layer):
class UserRepositoryImpl(
    private val localDao: UserDao,
    private val remoteApi: UserApi
) : UserReader, UserWriter { // ينفذ واجهتين مفصولتين تحقيقاً لـ ISP

    override fun getUser(id: String): Flow<User> = localDao.getUser(id)
    override suspend fun updateUser(user: User) { remoteApi.update(user) }
}

// واجهات دقيقة تحقق مبدأ ISP:
interface UserReader { // موجهة للـ Widgets والشاشات التي تقرأ فقط
    fun getUser(id: String): Flow<User>
}

interface UserWriter { // موجهة لشاشات التعديل فقط
    suspend fun updateUser(user: User)
}
```

استبدال الوراثة الهشة بكائنات مركبة عبر تفويض كوتلن (Kotlin Delegation):
```kotlin
// ❌ وراثة هشة: شجرة كلاسات Base عميقة يصعب تعديلها واختبارها:
open class BaseActivity : AppCompatActivity() { /* 500 سطر للتحليلات وشريط الأدوات */ }
open class AuthenticatedBaseActivity : BaseActivity() { /* 300 سطر للتحقق من الجلسة */ }
class OrdersActivity : AuthenticatedBaseActivity() { /* مقيدة بشجرة وراثة صلبة! */ }

// ✅ التركيب (Composition): سلوكيات مستقلة تُركب حسب الحاجة عبر Kotlin by:
interface SessionObserver {
    fun registerSessionTimeout(activity: Activity)
}
class SessionObserverImpl : SessionObserver { ... }

interface AnalyticsLogger {
    fun logScreen(name: String)
}
class FirebaseAnalyticsLogger : AnalyticsLogger { ... }

// تركيب السلوكيات في الشاشة دون وراثة هشة:
class OrdersActivity(
    private val session: SessionObserver = SessionObserverImpl(),
    private val analytics: AnalyticsLogger = FirebaseAnalyticsLogger()
) : AppCompatActivity(), SessionObserver by session, AnalyticsLogger by analytics {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate()
        registerSessionTimeout(this)
        logScreen("OrdersScreen")
    }
}
```

معالجة انتهاك LSP في شاشات الـ Fragments:
```kotlin
// ❌ انتهاك LSP: BaseFragment يفرض Toolbar على شاشات لا تحتاجه (كالشاشات المنبثقة والشاشات الكاملة):
abstract class LeakyBaseFragment : Fragment() {
    abstract fun setupToolbar(): Toolbar // فرض إلزامي!
}

class FullscreenPlayerFragment : LeakyBaseFragment() {
    override fun setupToolbar(): Toolbar {
        // 💥 يكسر LSP: يرمي استثناء أو يعيد null بطريقة غير متوقعة:
        throw UnsupportedOperationException("No toolbar in video player")
    }
}

// ✅ الحل المعماري المتوافق مع LSP: فصل القدرات في Interface أو Delegate:
abstract class SafeBaseFragment : Fragment() {
    // يحتوي فقط على السلوكيات العامة المشتركة بين 100% من الشاشات (مثل التحليلات أو الربط الأساسي)
}

// واجهة خاصة بالشاشات التي تمتلك Toolbar فقط:
interface ToolbarProvider {
    fun configureToolbar(toolbar: Toolbar)
}

class CatalogFragment : SafeBaseFragment(), ToolbarProvider {
    override fun configureToolbar(toolbar: Toolbar) { /* إعداد Toolbar للشاشة */ }
}

class SafePlayerFragment : SafeBaseFragment() {
    // لا ينفذ ToolbarProvider، ولا يكسر أي عقود!
}
```

تفكيك BaseActivity عملاق إلى كلاسات LifecycleObservers ومكونات Compose:
```kotlin
// 1. سلوك تتبع التحليلات معزول كمراقب لدورة الحياة:
class AnalyticsLifecycleObserver(private val tracker: AnalyticsTracker) : DefaultLifecycleObserver {
    override fun onResume(owner: LifecycleOwner) {
        tracker.logScreenVisit(owner.javaClass.simpleName)
    }
}

// 2. سلوك فحص الاتصال معزول كمراقب شبكة:
class NetworkMonitorObserver(private val networkMonitor: NetworkMonitor) : DefaultLifecycleObserver {
    override fun onStart(owner: LifecycleOwner) { networkMonitor.start() }
    override fun onStop(owner: LifecycleOwner) { networkMonitor.stop() }
}

// 3. النشاط أصبح نظيفاً تماماً بدون أي وراثة من BaseActivity مخصص:
@AndroidEntryPoint
class OrderActivity : ComponentActivity() {
    @Inject lateinit var analyticsObserver: AnalyticsLifecycleObserver
    @Inject lateinit var networkObserver: NetworkMonitorObserver

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate()
        // تركيب السلوكيات بنعومة واستقلالية:
        lifecycle.addObserver(analyticsObserver)
        lifecycle.addObserver(networkObserver)

        setContent {
            AppScaffold(title = "Orders") {
                OrderScreenContent()
            }
        }
    }
}
```

هندسة توجيه المدفوعات باستخدام نمط Strategy و Hilt Multibindings:
```kotlin
// 1. العقد الموحد للاستراتيجيات (Strategy Interface):
interface PaymentStrategy {
    val method: PaymentMethod
    suspend fun authorize(amountCents: Long, details: PaymentDetails): PaymentResult
}

// 2. تطبيقات مستقلة ومعزولة لكل مزود خدمة:
class StripePaymentStrategy @Inject constructor(...) : PaymentStrategy {
    override val method = PaymentMethod.CREDIT_CARD
    override suspend fun authorize(amountCents: Long, details: PaymentDetails) = ...
}

class PayPalPaymentStrategy @Inject constructor(...) : PaymentStrategy {
    override val method = PaymentMethod.PAYPAL
    override suspend fun authorize(amountCents: Long, details: PaymentDetails) = ...
}

// 3. الموجه (PaymentRouter) مغلق تماماً للتعديل ومفتوح للتوسيع (OCP):
class PaymentRouter @Inject constructor(
    private val strategies: Set<@JvmSuppressWildcards PaymentStrategy>
) {
    suspend fun routeAndPay(method: PaymentMethod, amountCents: Long, details: PaymentDetails): PaymentResult {
        val strategy = strategies.firstOrNull { it.method == method }
            ?: return PaymentResult.Error("Payment method not supported")
        return strategy.authorize(amountCents, details)
    }
}
```

المقارنة بين البويلربليت غير المجدي والتصميم البراغماتي النظيف:
